const input = $json;

const source = input.payment_success || input;

const onboardingInput = {
  lead_id: source.lead_id ?? input.lead_id ?? null,
  client_id: source.client_id ?? input.client_id ?? null,
  contract_id: source.contract_id ?? input.contract_id ?? null,
  invoice_id: source.invoice_id ?? input.invoice_id ?? null,
  payment_id: source.payment_id ?? input.payment_id ?? null,
  payment_status: source.payment_status ?? input.payment_status ?? null,
  contract_start: source.contract_start ?? input.contract_start ?? null,
  contract_term_months: source.contract_term_months ?? input.contract_term_months ?? null
};

const missingRequired = [
  'lead_id',
  'client_id'
].filter(key => onboardingInput[key] === null || onboardingInput[key] === undefined || onboardingInput[key] === '');

return [{
  json: {
    ...input,
    onboarding_input: onboardingInput,
    onboarding_mapping: {
      valid: missingRequired.length === 0,
      missing_required_fields: missingRequired,
      mapped_at: new Date().toISOString()
    }
  }
}];
